require_once __DIR__.'/../config/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT f.*,c.name carrier,c.phone,o.label origin_label,o.street origin_street,o.number origin_number,o.city origin_city,o.state origin_state,d.label destination_label,d.street destination_street,d.number destination_number,d.city destination_city,d.state destination_state FROM freights f JOIN carriers c ON c.id=f.carrier_id JOIN addresses o ON o.id=f.origin_id JOIN addresses d ON d.id=f.destination_id WHERE f.id=?");$s->execute([$id]);$f=$s->fetch();if(!$f){flash('warning','Frete não encontrado.');redirect('freights/index.php');}$s=$pdo->prepare('SELECT p.name,fp.quantity,p.weight FROM freight_products fp JOIN products p ON p.id=fp.product_id WHERE fp.freight_id=?');$s->execute([$id]);$items=$s->fetchAll();$pageTitle='Detalhes do frete';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><span class="eyebrow">OPERAÇÕES</span><h1>Frete #<?= (int)$f['id']?></h1><p>Detalhes da operação de transporte.</p></div><a class="btn btn-light" href="<?=e(url('freights/index.php'))?>">← Voltar aos fretes</a></div>
<section class="panel"><div class="panel-heading"><div><h2>Resumo da operação</h2><p>Criado em <?=e(date('d/m/Y H:i',strtotime($f['created_at'])))?></p></div><span class="status"><?=e($f['status'])?></span></div><div class="p-4"><div class="detail-grid"><div class="detail-item"><small>Transportador</small><strong><?=e($f['carrier'])?></strong><div class="muted"><?=e($f['phone'])?></div></div><div class="detail-item"><small>Data do frete</small><strong><?=e(date('d/m/Y',strtotime($f['freight_date'])))?></strong></div><div class="detail-item"><small>Origem</small><strong><?=e($f['origin_label'])?></strong><div class="muted"><?=e($f['origin_street'].', '.$f['origin_number'].' — '.$f['origin_city'].'/'.$f['origin_state'])?></div></div><div class="detail-item"><small>Destino</small><strong><?=e($f['destination_label'])?></strong><div class="muted"><?=e($f['destination_street'].', '.$f['destination_number'].' — '.$f['destination_city'].'/'.$f['destination_state'])?></div></div></div><?php if($f['notes']):?><p class="mt-3"><strong>Observações:</strong> <?=e($f['notes'])?></p><?php endif;?></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Produtos transportados</h2><p><?=count($items)?> item(ns) nesta operação.</p></div></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Peso unitário</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['name'])?></td><td><?= (int)$it['quantity']?></td><td><?=number_format($it['weight'],2,',','.')?> kg</td></tr><?php endforeach;?></tbody></table></div></section>
